// Simple asteroid dodge game targeting <canvas id="game"></canvas>
const canvas = document.getElementById('game');
if (!canvas) throw new Error('Canvas with id "game" not found');
const ctx = canvas.getContext('2d');
canvas.width = canvas.clientWidth || 800;
canvas.height = canvas.clientHeight || 600;

// ----- Game state -----
let ship = { x: canvas.width / 2, y: canvas.height - 30, w: 30, h: 20, speed: 5 };
let asteroids = [];
let score = 0;
let lastAsteroid = 0;
let gameOver = false;

// ----- Input -----
const keys = {};
window.addEventListener('keydown', e => keys[e.key] = true);
window.addEventListener('keyup', e => keys[e.key] = false);

function updateShip() {
  if (keys.ArrowLeft) ship.x -= ship.speed;
  if (keys.ArrowRight) ship.x += ship.speed;
  // keep inside canvas
  ship.x = Math.max(0, Math.min(canvas.width - ship.w, ship.x));
}

function spawnAsteroid() {
  const size = Math.random() * 30 + 10;
  const x = Math.random() * (canvas.width - size);
  const speed = 2 + Math.random() * 3 + score * 0.01; // speed up over time
  asteroids.push({ x, y: -size, size, speed });
}

function updateAsteroids(dt) {
  for (let i = asteroids.length - 1; i >= 0; i--) {
    const a = asteroids[i];
    a.y += a.speed;
    // remove off‑screen
    if (a.y - a.size > canvas.height) {
      asteroids.splice(i, 1);
      score++;
    } else if (rectCircleCollide(ship, a)) {
      gameOver = true;
    }
  }
}

function rectCircleCollide(rect, circle) {
  const distX = Math.abs(circle.x + circle.size / 2 - (rect.x + rect.w / 2));
  const distY = Math.abs(circle.y + circle.size / 2 - (rect.y + rect.h / 2));
  if (distX > rect.w / 2 + circle.size / 2) return false;
  if (distY > rect.h / 2 + circle.size / 2) return false;
  if (distX <= rect.w / 2) return true;
  if (distY <= rect.h / 2) return true;
  const dx = distX - rect.w / 2;
  const dy = distY - rect.h / 2;
  return dx * dx + dy * dy <= (circle.size / 2) * (circle.size / 2);
}

function draw() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  // ship (triangle)
  ctx.fillStyle = '#0f0';
  ctx.beginPath();
  ctx.moveTo(ship.x, ship.y + ship.h);
  ctx.lineTo(ship.x + ship.w / 2, ship.y);
  ctx.lineTo(ship.x + ship.w, ship.y + ship.h);
  ctx.closePath();
  ctx.fill();
  // asteroids
  ctx.fillStyle = '#888';
  asteroids.forEach(a => {
    ctx.beginPath();
    ctx.arc(a.x + a.size / 2, a.y + a.size / 2, a.size / 2, 0, Math.PI * 2);
    ctx.fill();
  });
  // score
  ctx.fillStyle = '#fff';
  ctx.font = '16px sans-serif';
  ctx.fillText('Score: ' + score, 10, 20);

  if (gameOver) {
    ctx.fillStyle = 'rgba(0,0,0,0.5)';
    ctx.fillRect(0, 0, canvas.width, canvas.height);
    ctx.fillStyle = '#f00';
    ctx.font = '48px sans-serif';
    ctx.textAlign = 'center';
    ctx.fillText('Game Over', canvas.width / 2, canvas.height / 2);
  }
}

let lastTime = performance.now();
function loop(time) {
  const dt = time - lastTime;
  lastTime = time;
  if (!gameOver) {
    updateShip();
    // spawn a new asteroid roughly every 800ms
    if (time - lastAsteroid > 800) { spawnAsteroid(); lastAsteroid = time; }
    updateAsteroids(dt);
  }
  draw();
  requestAnimationFrame(loop);
}
requestAnimationFrame(loop);
